-- Authored help guides (generated by `fierylib seed help --emit-sql`).
-- Source: fierylib/data/help/*.md. Do not edit by hand; edit the markdown
-- and regenerate.
-- Idempotent: matches on the primary keyword ("HelpEntry" has no unique key),
-- overwriting a legacy entry with the same primary keyword; a re-run changes 0 rows
-- (the UPDATE is skipped when the row already matches).

-- academy: Ethilien Training Academy
DO $do$
DECLARE v_id integer;
BEGIN
  SELECT id INTO v_id FROM "HelpEntry" WHERE keywords[1] = 'academy' ORDER BY id LIMIT 1;
  IF v_id IS NULL THEN
    SELECT id INTO v_id FROM "HelpEntry" WHERE 'academy' = ANY(keywords) ORDER BY id LIMIT 1;
  END IF;
  IF v_id IS NULL THEN
    INSERT INTO "HelpEntry"
      (keywords, title, content, min_level, category, usage, source_file, updated_at)
    VALUES (
      ARRAY['academy', 'ethilien-academy', 'training-academy', 'school']::text[],
      'Ethilien Training Academy',
      $help$The Ethilien Training Academy is the school for new characters. It
teaches the basics: moving, talking, fighting, gear and exploring. Every
new player is welcome, whatever race you picked and wherever you woke up.

FINDING IT
  The entrance is below the Forest Temple of Mielikki, in the Village of
  Mielikki (zone 30). The temple stands just north of Town Center. From
  the temple, type "down".
  Humans start inside the temple, so for them it is one word away. Other
  races start in their own homelands and need to walk to the village
  first. "areas" lists the zones; "where" tells you what room you are in.

AT THE ACADEMY
  A Recruiter waits at the gates. Talk to a teacher with "say": a
  teacher answers the words it listens for, and tells you the next one.
  You can leave at any time by saying "exit".

AFTER THE ACADEMY
  The Mielikki Farmlands (zone 80) is the newbie zone: easy monsters and
  safe fighting. "help newbie" has the rest of the first steps.

See also: NEWBIE.$help$,
      0,
      'guide',
      'academy',
      'data/help/academy.md',
      now()
    );
  ELSE
    UPDATE "HelpEntry" SET
      keywords = ARRAY['academy', 'ethilien-academy', 'training-academy', 'school']::text[],
      title = 'Ethilien Training Academy',
      content = $help$The Ethilien Training Academy is the school for new characters. It
teaches the basics: moving, talking, fighting, gear and exploring. Every
new player is welcome, whatever race you picked and wherever you woke up.

FINDING IT
  The entrance is below the Forest Temple of Mielikki, in the Village of
  Mielikki (zone 30). The temple stands just north of Town Center. From
  the temple, type "down".
  Humans start inside the temple, so for them it is one word away. Other
  races start in their own homelands and need to walk to the village
  first. "areas" lists the zones; "where" tells you what room you are in.

AT THE ACADEMY
  A Recruiter waits at the gates. Talk to a teacher with "say": a
  teacher answers the words it listens for, and tells you the next one.
  You can leave at any time by saying "exit".

AFTER THE ACADEMY
  The Mielikki Farmlands (zone 80) is the newbie zone: easy monsters and
  safe fighting. "help newbie" has the rest of the first steps.

See also: NEWBIE.$help$,
      min_level = 0,
      category = 'guide',
      usage = 'academy',
      source_file = 'data/help/academy.md',
      updated_at = now()
    WHERE id = v_id
      AND (keywords, title, content, min_level, category, usage, source_file)
          IS DISTINCT FROM (ARRAY['academy', 'ethilien-academy', 'training-academy', 'school']::text[], 'Ethilien Training Academy', $help$The Ethilien Training Academy is the school for new characters. It
teaches the basics: moving, talking, fighting, gear and exploring. Every
new player is welcome, whatever race you picked and wherever you woke up.

FINDING IT
  The entrance is below the Forest Temple of Mielikki, in the Village of
  Mielikki (zone 30). The temple stands just north of Town Center. From
  the temple, type "down".
  Humans start inside the temple, so for them it is one word away. Other
  races start in their own homelands and need to walk to the village
  first. "areas" lists the zones; "where" tells you what room you are in.

AT THE ACADEMY
