-- rest: Resting and Posture
DO $do$
DECLARE v_id integer;
BEGIN
  SELECT id INTO v_id FROM "HelpEntry" WHERE keywords[1] = 'rest' ORDER BY id LIMIT 1;
  IF v_id IS NULL THEN
    SELECT id INTO v_id FROM "HelpEntry" WHERE 'rest' = ANY(keywords) ORDER BY id LIMIT 1;
  END IF;
  IF v_id IS NULL THEN
    INSERT INTO "HelpEntry"
      (keywords, title, content, min_level, category, usage, source_file, updated_at)
    VALUES (
      ARRAY['rest', 'wake', 'sleeping', 'sit', 'stand']::text[],
      'Resting and Posture',
      $help$Your posture decides how fast you recover. Per second:

  stand     stamina only; hit points do not come back by themselves
  sit       a little hit points, more stamina
  rest      more hit points, more stamina
  sleep     the most of both, but you are deaf and blind to the room

"stand" gets you up and "wake" ends sleep. Being hit while sitting, resting
or asleep hurts more, and you cannot recover while you fight. You may still
fight from any posture; the game does not stand you up.

Meditating (MEDITATE) shortens spell slot recovery for casters.

See also: MEDITATE, SLOTS, FLEE.$help$,
      0,
      'command',
      'sit | rest | sleep | stand | wake',
      'data/help/rest.md',
      now()
    );
  ELSE
    UPDATE "HelpEntry" SET
      keywords = ARRAY['rest', 'wake', 'sleeping', 'sit', 'stand']::text[],
      title = 'Resting and Posture',
      content = $help$Your posture decides how fast you recover. Per second:

  stand     stamina only; hit points do not come back by themselves
  sit       a little hit points, more stamina
  rest      more hit points, more stamina
  sleep     the most of both, but you are deaf and blind to the room

"stand" gets you up and "wake" ends sleep. Being hit while sitting, resting
or asleep hurts more, and you cannot recover while you fight. You may still
fight from any posture; the game does not stand you up.

Meditating (MEDITATE) shortens spell slot recovery for casters.

See also: MEDITATE, SLOTS, FLEE.$help$,
      min_level = 0,
      category = 'command',
      usage = 'sit | rest | sleep | stand | wake',
      source_file = 'data/help/rest.md',
      updated_at = now()
    WHERE id = v_id
      AND (keywords, title, content, min_level, category, usage, source_file)
          IS DISTINCT FROM (ARRAY['rest', 'wake', 'sleeping', 'sit', 'stand']::text[], 'Resting and Posture', $help$Your posture decides how fast you recover. Per second:

  stand     stamina only; hit points do not come back by themselves
  sit       a little hit points, more stamina
  rest      more hit points, more stamina
  sleep     the most of both, but you are deaf and blind to the room

"stand" gets you up and "wake" ends sleep. Being hit while sitting, resting
or asleep hurts more, and you cannot recover while you fight. You may still
fight from any posture; the game does not stand you up.

Meditating (MEDITATE) shortens spell slot recovery for casters.

See also: MEDITATE, SLOTS, FLEE.$help$, 0, 'command', 'sit | rest | sleep | stand | wake', 'data/help/rest.md');
  END IF;
END
