      usage = 'study | study {spell}',
      source_file = 'data/help/study.md',
      updated_at = now()
    WHERE id = v_id
      AND (keywords, title, content, min_level, category, usage, source_file)
          IS DISTINCT FROM (ARRAY['study', 'memorize', 'pray']::text[], 'Study', $help$Casters learn their spells with STUDY. Skills come with your class as you
level and need no study.

  study              list the spells you can learn right now
