-- torch: Torches and Light
DO $do$
DECLARE v_id integer;
BEGIN
  SELECT id INTO v_id FROM "HelpEntry" WHERE keywords[1] = 'torch' ORDER BY id LIMIT 1;
  IF v_id IS NULL THEN
    SELECT id INTO v_id FROM "HelpEntry" WHERE 'torch' = ANY(keywords) ORDER BY id LIMIT 1;
  END IF;
  IF v_id IS NULL THEN
    INSERT INTO "HelpEntry"
      (keywords, title, content, min_level, category, usage, source_file, updated_at)
    VALUES (
      ARRAY['torch', 'torches', 'lantern', 'lanterns']::text[],
      'Torches and Light',
      $help$At night and underground the world is dark: you cannot see the room, the
exits or other characters. Some races see in the dark; most need a light.

  light {torch}        turn a carried light on
  extinguish {torch}   turn it off to save its fuel

A torch burns for a while and then goes out. General stores sell torches
and lanterns: Aaron's General Store in the Village of Mielikki (zone 30)
is one. Buy one before you go out after dark.

See also: LIGHT, SHOPS, NEWBIE.$help$,
      0,
      'command',
      'light {torch} | extinguish {torch}',
      'data/help/torch.md',
      now()
    );
